/**
 * app.js — reads SITE config from content.js and renders the page
 * Do not edit this file unless you want to change layout behaviour.
 */

(function () {
  "use strict";

  /* ── Apply CSS variables from color config ─────────────── */
  function applyColors() {
    const r = document.documentElement.style;
    const c = SITE.colors;
    r.setProperty("--bg",      c.background);
    r.setProperty("--surface", c.surface);
    r.setProperty("--primary", c.primary);
    r.setProperty("--accent",  c.accent);
    r.setProperty("--accent2", c.accent2);
    r.setProperty("--muted",   c.muted);
    r.setProperty("--border",  c.border);
  }

  /* ── Meta tags ─────────────────────────────────────────── */
  function applyMeta() {
    const m = SITE.meta;
    document.documentElement.lang = m.lang;
    document.title = m.title;
    document.querySelector('meta[name="description"]').content = m.description;
  }

  /* ── Navigation ─────────────────────────────────────────── */
  function renderNav() {
    const n = SITE.nav;
    const nav = document.getElementById("site-nav");
    if (!nav) return;

    const logo = nav.querySelector(".nav-logo");
    logo.textContent = n.logo;

    const list = nav.querySelector(".nav-links");
    list.innerHTML = n.links
      .map(l => `<li><a href="${l.href}">${l.label}</a></li>`)
      .join("");

    const cta = nav.querySelector(".nav-cta");
    cta.textContent = n.cta.label;
    cta.href = n.cta.href;
    if (n.cta.newTab) {
      cta.target = "_blank";
      cta.rel = "noopener";
    }
  }

  /* ── Hero ───────────────────────────────────────────────── */
  function renderHero() {
    const h = SITE.hero;
    const section = document.getElementById("hero");
    if (!section) return;

    section.querySelector(".hero-eyebrow").textContent  = h.eyebrow;
    section.querySelector(".hero-headline").textContent = h.headline;
    section.querySelector(".hero-subline").textContent  = h.subline;

    const cta = section.querySelector(".hero-cta");
    cta.textContent = h.cta.label;
    cta.href        = h.cta.href;
    if (h.cta.newTab) {
      cta.target = "_blank";
      cta.rel    = "noopener";
    }

    const demoCta = section.querySelector(".hero-demo-cta");
    demoCta.textContent = h.demoCta.label;
    demoCta.href        = h.demoCta.href;
    if (h.demoCta.newTab) {
      demoCta.target = "_blank";
      demoCta.rel    = "noopener";
    }
  }

  /* ── Features ───────────────────────────────────────────── */
  function renderFeatures() {
    const f = SITE.features;
    const section = document.getElementById("features");
    if (!section) return;

    section.querySelector(".section-label").textContent   = f.sectionLabel;
    section.querySelector(".section-heading").textContent = f.heading;

    const list = section.querySelector(".features-list");
    list.innerHTML = f.items.map(item => `
      <div class="feature-item">
        <span class="feature-icon">${item.icon}</span>
        <h3 class="feature-title">${item.title}</h3>
        <p class="feature-body">${item.body}</p>
      </div>
    `).join("");
  }

  /* ── About ──────────────────────────────────────────────── */
  function renderAbout() {
    const a = SITE.about;
    const section = document.getElementById("about");
    if (!section) return;

    section.querySelector(".section-label").textContent   = a.sectionLabel;
    section.querySelector(".section-heading").textContent = a.heading;

    const textBlock = section.querySelector(".about-text");
    textBlock.innerHTML = a.paragraphs
      .map(p => `<p>${p}</p>`)
      .join("");

    const statsEl = section.querySelector(".about-stats");
    statsEl.innerHTML = a.stats.map(s => `
      <div class="stat">
        <span class="stat-value">${s.value}</span>
        <span class="stat-label">${s.label}</span>
      </div>
    `).join("");
  }

  /* ── Signup ─────────────────────────────────────────────── */
  function renderSignup() {
    const s = SITE.signup;
    const section = document.getElementById("signup");
    if (!section) return;

    section.querySelector(".section-label").textContent   = s.sectionLabel;
    section.querySelector(".section-heading").textContent = s.heading;
    section.querySelector(".signup-subline").textContent  = s.subline;

    const cta = section.querySelector(".signup-cta");
    cta.textContent = s.cta.label;
    cta.href        = s.cta.href;
    if (s.cta.newTab) {
      cta.target = "_blank";
      cta.rel    = "noopener";
    }
  }

  /* ── Footer ─────────────────────────────────────────────── */
  function renderFooter() {
    const f = SITE.footer;
    const footer = document.getElementById("site-footer");
    if (!footer) return;

    footer.querySelector(".footer-copy").innerHTML = f.copyright;

    const socialsList = footer.querySelector(".footer-socials");
    socialsList.innerHTML = f.socials
      .map(s => `<li><a href="${s.href}" target="_blank" rel="noopener">${s.label}</a></li>`)
      .join("");
  }

  /* ── Smooth-scroll active nav link highlighting ────────── */
  function initScrollSpy() {
    if (!("IntersectionObserver" in window)) return;
    const sections = document.querySelectorAll("section[id]");
    const navLinks = document.querySelectorAll(".nav-links a");

    const observer = new IntersectionObserver(
      entries => {
        entries.forEach(e => {
          if (e.isIntersecting) {
            navLinks.forEach(a => a.classList.remove("active"));
            const active = document.querySelector(`.nav-links a[href="#${e.target.id}"]`);
            if (active) active.classList.add("active");
          }
        });
      },
      { rootMargin: "-40% 0px -55% 0px" }
    );

    sections.forEach(s => observer.observe(s));
  }

  /* ── Mobile nav toggle ──────────────────────────────────── */
  function initMobileNav() {
    const toggle = document.querySelector(".nav-toggle");
    const menu   = document.querySelector(".nav-links");
    if (!toggle || !menu) return;
    toggle.addEventListener("click", () => {
      const open = menu.classList.toggle("open");
      toggle.setAttribute("aria-expanded", open);
    });
    // close on link click
    menu.querySelectorAll("a").forEach(a =>
      a.addEventListener("click", () => {
        menu.classList.remove("open");
        toggle.setAttribute("aria-expanded", false);
      })
    );
  }

  /* ── Animate elements on scroll ────────────────────────── */
  function initReveal() {
    if (!("IntersectionObserver" in window)) {
      document.querySelectorAll("[data-reveal]").forEach(el => el.classList.add("revealed"));
      return;
    }
    const els = document.querySelectorAll("[data-reveal]");
    const obs = new IntersectionObserver(
      entries => {
        entries.forEach(e => {
          if (e.isIntersecting) {
            e.target.classList.add("revealed");
            obs.unobserve(e.target);
          }
        });
      },
      { threshold: 0.12 }
    );
    els.forEach(el => obs.observe(el));
  }

  /* ── Boot ───────────────────────────────────────────────── */
  document.addEventListener("DOMContentLoaded", function () {
    // Enable JS-driven reveal animations (progressive enhancement)
    document.documentElement.classList.add("js");
    applyColors();
    applyMeta();
    renderNav();
    renderHero();
    renderFeatures();
    renderAbout();
    renderSignup();
    renderFooter();
    initScrollSpy();
    initMobileNav();
    initReveal();
  });

})();
